# 复制同样的函数定义做纯函数测试
def div(a, b):
    if b == 0:
        raise ValueError(f'除数不能为 0，得到的 b = {b}')
    return a / b

# 正常情况
for a,b in [(10,2),(5,2),(-4,2),(7.5,3),(0,5)]:
    print(f'div({a},{b}) =', div(a,b))

# 除0抛 ValueError
for a,b in [(5,0),(1,0),(0,0),(-3,0)]:
    try:
        div(a,b)
        print(f'FAIL {a},{b}: 没报错')
    except ValueError as e:
        print(f'OK ValueError ({a},{b}) ->', e)
    except ZeroDivisionError:
        print(f'FAIL ({a},{b}): 抛了 ZeroDivisionError')
